[codeblocks] [gdscript] extends DV_DetailPanel
func _ready() -> void: set_title("Character Profile")
var name_field := DV_Field.new() name_field.label = "Name" name_field.value = "Kaelen" name_field.group = "Identity" add_field(name_field)
var hp := DV_Field.new() hp.label = "Health" hp.value = "75/100" hp.progress_percent = 75 hp.group = "Stats" hp.accent = Color.DARK_GREEN add_field(hp) [/gdscript] [/codeblocks]
